import{_ as t,a as o,b as i,c as a,d as n,e as r,f as s}from"./chunks/save-profile.Bb8HbfjZ.js";import{_ as c,o as l,c as h,aj as d}from"./chunks/framework.C6uXqnaX.js";const x=JSON.parse('{"title":"Profile your application","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"tools/devtools/profiler.md","filePath":"tools/devtools/profiler.md"}'),p={name:"tools/devtools/profiler.md"};function g(u,e,m,f,b,y){return l(),h("div",null,e[0]||(e[0]=[d('<h1 id="profile-your-application" tabindex="-1">Profile your application <a class="header-anchor" href="#profile-your-application" aria-label="Permalink to &quot;Profile your application&quot;">​</a></h1><p>The <strong>Profiler</strong> tab lets you visualize the execution of Angular&#39;s change detection. This is useful for determining when and how change detection impacts your application&#39;s performance.</p><img src="'+t+'" alt="A screenshot of the &#39;Profiler&#39; tab which reads &#39;Click the play button to start a new recording, or upload a json file containing profiler data.&#39; Next to this is a record button to begin recording a new profile as well as a file picker to select an existing profile."><p>The Profiler tab lets you start profiling the current application or import an existing profile from a previous run. To start profiling your application, hover over the circle in the top-left corner within the <strong>Profiler</strong> tab and click <strong>Start recording</strong>.</p><p>During profiling, Angular DevTools captures execution events, such as change detection and lifecycle hook execution. Interact with your application to trigger change detection and generate data Angular DevTools can use. To finish recording, click the circle again to <strong>Stop recording</strong>.</p><p>You can also import an existing recording. Read more about this feature in the <a href="/tools/devtools/profiler#import-and-export-recordings">Import recording</a> section.</p><h2 id="understand-your-application-s-execution" tabindex="-1">Understand your application&#39;s execution <a class="header-anchor" href="#understand-your-application-s-execution" aria-label="Permalink to &quot;Understand your application&#39;s execution&quot;">​</a></h2><p>After recording or importing a profile, Angular DevTools displays a visualization of change detection cycles.</p><img src="'+o+'" alt="A screenshot of the &#39;Profiler&#39; tab after a profile has been recorded or uploaded. It displays a bar chart illustrating various change detection cycles with some text which reads &#39;Select a bar to preview a particular change detection cycle&#39;."><p>Each bar in the sequence represents a change detection cycle in your app. The taller a bar is, the longer the application spent running change detection in this cycle. When you select a bar, DevTools displays useful information about it including:</p><ul><li>A bar chart with all the components and directives that it captured during this cycle</li><li>How much time Angular spent running change detection in this cycle.</li><li>An estimated frame rate as experienced by the user (if below 60fps)</li></ul><img src="'+i+'" alt="A screenshot of the &#39;Profiler&#39; tab. A single bar has been selected by the user and a nearby dropdown menu displays &#39;Bar chart`, showing a second bar chart underneath it. The new chart has two bars which take up the majority of the space, one labeled `TodosComponent` and the other labeled `NgForOf`. The other bars are small enough to be negligible in comparison."><h2 id="understand-component-execution" tabindex="-1">Understand component execution <a class="header-anchor" href="#understand-component-execution" aria-label="Permalink to &quot;Understand component execution&quot;">​</a></h2><p>The bar chart displayed after clicking on a change detection cycle displays a detailed view about how much time your application spent running change detection in that particular component or directive.</p><p>This example shows the total time spent by the <code>NgForOf</code> directive and which method was called on it.</p><img src="'+a+'" alt="A screenshot of the &#39;Profiler&#39; tab where the `NgForOf` bar is selected. A detailed view of `NgForOf` is visible to the right where it lists &#39;Total time spent: 1.76 ms&#39;. It includes a with exactly one row, listing `NgForOf` as a directives with an `ngDoCheck` method which took 1.76 ms. It also includes a list labeled &#39;Parent Hierarchy&#39; containing the parent components of this directive."><h2 id="hierarchical-views" tabindex="-1">Hierarchical views <a class="header-anchor" href="#hierarchical-views" aria-label="Permalink to &quot;Hierarchical views&quot;">​</a></h2><img src="'+n+'" alt="A screenshot of the &#39;Profiler&#39; tab. A single bar has been selected by the user and a nearby dropdown menu now displays &#39;Flame graph&#39;, showing a flame graph underneath it. The flame graph starts with a row called &#39;Entire application&#39; and another row called &#39;AppComponent&#39;. Beneath those, the rows start to break up into multiple items, starting with `[RouterOutlet]` and `DemoAppComponent` on the third row. A few layers deep, one cell is highlighted red."><p>You can also visualize the change detection execution in a flame graph-like view.</p><p>Each tile in the graph represents an element on the screen at a specific position in the render tree. For example, consider a change detection cycle where a <code>LoggedOutUserComponent</code> is removed and in its place Angular rendered a <code>LoggedInUserComponent</code>. In this scenario both components will be displayed in the same tile.</p><p>The x-axis represents the full time it took to render this change detection cycle. The y-axis represents the element hierarchy. Running change detection for an element requires rendering its directives and child components. Together, this graph visualizes which components are taking the longest time to render and where that time is going.</p><p>Each tile is colored depending on how much time Angular spent there. Angular DevTools determines the intensity of the color by the time spent relative to the tile where rendering took the most time.</p><p>When you click on a certain tile, you&#39;ll see details about it in the panel on the right. Double-clicking the tile zooms it in so you can more easily view its nested children.</p><h2 id="debug-change-detection-and-onpush-components" tabindex="-1">Debug change detection and <code>OnPush</code> components <a class="header-anchor" href="#debug-change-detection-and-onpush-components" aria-label="Permalink to &quot;Debug change detection and `OnPush` components&quot;">​</a></h2><p>Normally, the graph visualizes the time it takes to <em>render</em> an application, for any given change detection frame. However some components such as <code>OnPush</code> components will only re-render if their input properties change. It can be useful to visualize the flame graph without these components for particular frames.</p><p>To visualize only the components in a change detection frame that went through the change detection process, select the <strong>Change detection</strong> checkbox at the top, above the flame graph.</p><p>This view highlights all the components that went through change detection and displays those that did not in gray, such as <code>OnPush</code> components that did not re-render.</p><img src="'+r+'" alt="A screenshot of the &#39;Profiler&#39; tab displaying a flame chart visualization of a change detection cycle. A checkbox labeled &#39;Show only change detection&#39; is now checked. The flame graph looks very similar to before, however the color of components has changed from orange to blue. Several tiles labeled `[RouterOutlet]` are no longer highlighted with any color."><h2 id="import-and-export-recordings" tabindex="-1">Import and export recordings <a class="header-anchor" href="#import-and-export-recordings" aria-label="Permalink to &quot;Import and export recordings&quot;">​</a></h2><p>Click the <strong>Save Profile</strong> button at the top-right of a recorded profiling session to export it as a JSON file and save it to the disk. Later, import the file in the initial view of the profiler by clicking the <strong>Choose file</strong> input.</p><img src="'+s+'" alt="A screenshot of the &#39;Profiler&#39; tab displaying change detection cycles. On the right side a &#39;Save Profile&#39; button is visible.">',31)]))}const _=c(p,[["render",g]]);export{x as __pageData,_ as default};
